package calc

func digitsum(n int64) int64 {
	var total int64
	for i := int64(0); i < n; i++ {
		for x := i; x > 1; x /= 10 {
			total += x % 10
		}
	}
	return total
}

package calc

import "testing"

func TestDigitsum(t *testing.T) {
	if got := digitsum(10); got != 45 {
		t.Errorf("digitsum(10) = %d, want 45", got)
	}
	if got := digitsum(100); got != 900 {
		t.Errorf("digitsum(100) = %d, want 900", got)
	}
}
